from __future__ import annotations

from pathlib import Path

ROOT = Path.cwd()
SELF = Path(__file__).resolve()
state: dict[str, str] = {}
original: dict[str, str] = {}
new_paths: set[str] = set()
removed_paths: set[str] = set()


def disk_read(path: str) -> str:
    p = ROOT / path
    if not p.exists():
        raise SystemExit(f"[STOP] Missing expected file: {path}")
    return p.read_text(encoding="utf-8")


def get(path: str) -> str:
    if path in state:
        return state[path]
    text = disk_read(path)
    original[path] = text
    state[path] = text
    return text


def put(path: str, text: str) -> None:
    state[path] = text


def apply_replace(path: str, old: str, new: str, label: str) -> None:
    s = get(path)
    if old not in s:
        raise SystemExit(
            f"[STOP] Could not find expected code for: {label}\n"
            f"File: {path}\n"
            "No project files were written. Your local copy differs from the Parley main branch this updater was built for."
        )
    put(path, s.replace(old, new, 1))


def apply_section(path: str, start: str, end: str | None, replacement: str, label: str) -> None:
    s = get(path)
    a = s.find(start)
    if a < 0:
        raise SystemExit(
            f"[STOP] Could not find start marker for {label}: {path}\nNo project files were written."
        )
    if end is None:
        b = len(s)
        suffix = ""
    else:
        b = s.find(end, a)
        if b < 0:
            raise SystemExit(
                f"[STOP] Could not find end marker for {label}: {path}\nNo project files were written."
            )
        suffix = s[b:]
    put(path, s[:a] + replacement.rstrip() + "\n\n" + suffix)



