SECTIONS = [('bot/views/self_post.py', 'def _instructions(channel: discord.TextChannel, seconds: int, user: discord.abc.User) -> str:\n', 'def _previous_overwrite(', 'def _instructions(\n    channel: discord.TextChannel,\n    seconds: int,\n    user: discord.abc.User,\n    *,\n    post_title: str = "ad",\n) -> str:\n    minutes = max(1, seconds // 60)\n    url = f"https://discord.com/channels/{channel.guild.id}/{channel.id}"\n    return (\n        "## Your posting window is open\\n"\n        f"**Go to:** [#{channel.name}]({url})\\n"\n        f"**Time limit:** {minutes} minute{\'s\' if minutes != 1 else \'\'}\\n\\n"\n        f"Send your {post_title.lower()} as **one message**. As soon as you post, Waypoint locks your "\n        "posting permission again automatically.\\n"\n        "-# I also pinged only you in the channel so it is easy to find."\n    )\n', 'posting instructions'), ('bot/views/partnership.py', '@register_action("find")\nasync def start_find_flow', 'class CategoryView(OwnedView):', '@register_action("find")\nasync def start_find_flow(interaction: discord.Interaction) -> None:\n    """Browse matches immediately; ask for a source server only when the user has several."""\n    bot = get_bot(interaction)\n    async with bot.db.session() as session:\n        sources = await represented_listings(bot, session, interaction.user.id)\n        guilds = await repository.get_guilds(session, [s.guild_id for s in sources])\n\n    if len(sources) > 1:\n        async def picked(inter: discord.Interaction, guild_id: int) -> None:\n            await FinderView(bot, inter.user.id, category=ANY, source_id=guild_id).show(inter)\n\n        embed = discord.Embed(\n            title="Browse Partners",\n            description="Which server are you finding a partner for?",\n            color=bot.runtime.bot.color_primary,\n        )\n        await reply(\n            interaction,\n            embed=embed,\n            view=GuildPickerView(\n                interaction.user.id,\n                [(s.guild_id, guild_name(guilds, s.guild_id)) for s in sources],\n                picked,\n                placeholder="Choose your server",\n            ),\n        )\n        return\n\n    source_id = sources[0].guild_id if sources else None\n    await FinderView(bot, interaction.user.id, category=ANY, source_id=source_id).show(interaction)\n', 'simple Find Partners entry flow'), ('bot/views/partnership.py', '    def build(self) -> None:\n        self.clear_items()\n        assert self.current is not None\n', '    async def show(self, interaction: discord.Interaction, notice: str | None = None) -> None:\n', '    def build(self) -> None:\n        self.clear_items()\n        assert self.current is not None\n        gid = self.current.guild_id\n\n        request = discord.ui.Button(label="Send Partner Request", style=discord.ButtonStyle.success, row=0)\n        request.callback = self._request  # type: ignore[method-assign]\n        self.add_item(request)\n\n        nxt = discord.ui.Button(label="Next Match", style=discord.ButtonStyle.primary, row=0)\n        nxt.callback = self._next  # type: ignore[method-assign]\n        self.add_item(nxt)\n\n        partner_url = listing_jump_url(\n            self.bot.runtime.hub.main_guild_id,\n            self.current.partner_channel_id,\n            self.current.partner_message_id,\n        )\n        if partner_url:\n            self.add_item(discord.ui.Button(label="View Partner Post", url=partner_url, row=0))\n        else:\n            self.add_item(view_ad_button(self.bot, gid, label="View Server Ad", row=0))\n\n        self.add_item(home_button(self.bot, row=1))\n', 'distinct FinderView buttons'), ('bot/views/partnership.py', '# ---------------------------------------------------------------- looking for partners\n', None, '# ---------------------------------------------------------------- partner posting\n\n\n@register_action("looking")\nasync def start_looking_post(interaction: discord.Interaction) -> None:\n    """Legacy action ID kept so old buttons now open the new partner-post manager."""\n    from bot.views.partner_posts import start_partner_posts\n\n    await start_partner_posts(interaction)\n', 'replace old structured looking-post flow'), ('bot/views/welcome.py', 'def control_panel(bot: WaypointBot, *, staff: bool = False) -> tuple[str, discord.ui.View]:\n', 'def set_listing_button_label(', 'def control_panel(bot: WaypointBot, *, staff: bool = False) -> tuple[str, discord.ui.View]:\n    """The DM home: five clear user actions, plus Settings for staff."""\n    content = templates.render(bot.runtime, "dm_home")\n    if staff and bot.runtime.hub.mode != "live":\n        content += f"\\n-# Mode: {\'🧪 TEST\' if bot.runtime.hub.mode == \'test\' else \'🔴 OFF\'}"\n    view = persistent_view(\n        action_button(bot, "post", row=0),\n        action_button(bot, "find", row=0),\n        action_button(bot, "servers", row=1),\n        action_button(bot, "partner_posts", row=1),\n        action_button(bot, "requests", row=2),\n        action_button(bot, "settings", row=3) if staff else None,\n    )\n    return content, view\n', 'clean DM control panel'), ('bot/views/welcome.py', 'def listings_panel(bot: WaypointBot) -> tuple[str, discord.ui.View]:\n', 'def join_message(', 'def listings_panel(bot: WaypointBot) -> tuple[str, discord.ui.View]:\n    """Server Directory controls: only server-ad actions."""\n    view = persistent_view(\n        action_button(bot, "post", row=0),\n        action_button(bot, "servers", row=0),\n        action_button(bot, "relist", row=1),\n    )\n    return templates.render(bot.runtime, "listings_panel"), view\n\n\ndef looking_panel(bot: WaypointBot) -> tuple[str, discord.ui.View]:\n    """Find-a-Partner controls: deliberately different from Server Directory."""\n    view = persistent_view(\n        action_button(bot, "find", row=0),\n        action_button(bot, "looking", row=0),\n        action_button(bot, "partner_posts", row=1),\n    )\n    return templates.render(bot.runtime, "looking_panel"), view\n\n\ndef _hub_channel_url(bot: WaypointBot, channel_id: int | None) -> str | None:\n    guild_id = bot.runtime.hub.main_guild_id\n    if not guild_id or not channel_id:\n        return None\n    return f"https://discord.com/channels/{guild_id}/{channel_id}"\n\n\ndef welcome_panel(bot: WaypointBot) -> tuple[str, discord.ui.View]:\n    """Start Here is a tiny router, not another management dashboard."""\n    directory_url = _hub_channel_url(bot, bot.runtime.hub.listings_channel_id)\n    partner_url = _hub_channel_url(bot, bot.runtime.hub.looking_channel_id)\n    view = persistent_view(\n        discord.ui.Button(label="Server Directory", url=directory_url, row=0) if directory_url else None,\n        discord.ui.Button(label="Find a Partner", url=partner_url, row=0) if partner_url else None,\n        action_button(bot, "post", row=1),\n        action_button(bot, "looking", row=1),\n    )\n    return templates.render(bot.runtime, "welcome"), view\n', 'separate public channel panels'), ('bot/services/panels.py', '    async def ensure_directory_locked(self) -> bool:\n', '    # ------------------------------------------------------------ low-level message helpers\n', '    async def ensure_directory_locked(self) -> bool:\n        """Keep both public feeds read-only except for Parley\'s short posting windows."""\n        channels = [self.listings_channel(), self.looking_channel()]\n        found = False\n        all_ok = True\n        for channel in channels:\n            if channel is None or channel.guild.me is None:\n                continue\n            found = True\n            me = channel.guild.me\n            perms = channel.permissions_for(me)\n            if not perms.manage_roles:\n                all_ok = False\n                continue\n            everyone = channel.guild.default_role\n            current = channel.overwrites_for(everyone)\n            allow, deny = current.pair()\n            updated = discord.PermissionOverwrite.from_pair(allow, deny)\n            updated.send_messages = False\n            if hasattr(updated, "create_public_threads"):\n                updated.create_public_threads = False\n            if hasattr(updated, "send_messages_in_threads"):\n                updated.send_messages_in_threads = False\n            try:\n                await channel.set_permissions(everyone, overwrite=updated, reason="Parley: lock managed feed")\n            except discord.HTTPException as exc:\n                log.warning("Could not lock #%s: %s", channel.name, exc)\n                all_ok = False\n        return found and all_ok\n', 'lock both public feeds'), ('bot/services/panels.py', '    async def take_down_listing(self, listing) -> None:\n', '    async def _is_newest(', '    async def take_down_listing(self, listing) -> None:\n        """Delete every public post owned by a listing after removal/suspension/ban."""\n        if listing is None:\n            return\n        await self._delete(listing.channel_id, listing.controls_message_id)\n        await self._delete(listing.channel_id, listing.message_id)\n        await self._delete(listing.partner_channel_id, listing.partner_controls_message_id)\n        await self._delete(listing.partner_channel_id, listing.partner_message_id)\n        async with self.bot.db.session() as session:\n            await listing_service.record_message(session, guild_id=listing.guild_id, channel_id=None, message_id=None)\n            current = await repository.get_listing(session, listing.guild_id)\n            if current is not None:\n                current.partner_ad_text = None\n                current.partner_channel_id = None\n                current.partner_message_id = None\n                current.partner_controls_message_id = None\n                current.partner_posted_at = None\n', 'remove partner post with listing'), ('bot/core.py', '        # #server-directory is not a chat channel.', '    async def on_message_edit(', '        # Server Directory and Find a Partner are controlled feeds. A manager gets\n        # a short one-message window; everything else is removed.\n        protected = {\n            cid\n            for cid in (self.hub.listings_channel_id, self.hub.looking_channel_id)\n            if cid\n        }\n        if message.channel.id in protected:\n            from bot.views import self_post\n\n            if self_post.is_active_submission(message.channel.id, message.author.id, message.id):\n                return\n            try:\n                await message.delete()\n            except discord.HTTPException as exc:\n                log.warning("Could not remove unauthorized feed message %s: %s", message.id, exc)\n            return\n', 'protect both public feeds'), ('bot/core.py', '        # If an owner deletes their own direct-post ad,', '    async def on_guild_channel_delete(', '        # If an owner deletes their own direct-post server ad, keep its control\n        # state valid until they replace it.\n        if payload.channel_id == self.hub.listings_channel_id:\n            async with self.db.session() as session:\n                listing = await repository.get_listing_by_message(session, payload.message_id)\n            if listing is not None:\n                await self.panels.self_post_message_removed(listing.guild_id)\n                log.info("listing.self_post_deleted guild_id=%s message_id=%s", listing.guild_id, payload.message_id)\n        elif payload.channel_id == self.hub.looking_channel_id:\n            from bot.views import partner_posts\n\n            await partner_posts.handle_raw_delete(self, payload.channel_id, payload.message_id)\n', 'partner raw-delete handling')]
NEW_FILES = {'migrations/versions/0006_partner_posts.py': '"""Independent owner-authored partner posts.\n\nRevision ID: 0006\nRevises: 0005\nCreate Date: 2026-09-23\n"""\n\nfrom __future__ import annotations\n\nfrom collections.abc import Sequence\n\nimport sqlalchemy as sa\nfrom alembic import op\n\nrevision: str = "0006"\ndown_revision: str | None = "0005"\nbranch_labels: str | Sequence[str] | None = None\ndepends_on: str | Sequence[str] | None = None\n\n\ndef upgrade() -> None:\n    with op.batch_alter_table("listings", schema=None) as batch_op:\n        batch_op.add_column(sa.Column("partner_ad_text", sa.Text(), nullable=True))\n        batch_op.add_column(sa.Column("partner_channel_id", sa.BigInteger(), nullable=True))\n        batch_op.add_column(sa.Column("partner_message_id", sa.BigInteger(), nullable=True))\n        batch_op.add_column(sa.Column("partner_controls_message_id", sa.BigInteger(), nullable=True))\n        batch_op.add_column(sa.Column("partner_posted_at", sa.DateTime(timezone=True), nullable=True))\n\n\ndef downgrade() -> None:\n    with op.batch_alter_table("listings", schema=None) as batch_op:\n        batch_op.drop_column("partner_posted_at")\n        batch_op.drop_column("partner_controls_message_id")\n        batch_op.drop_column("partner_message_id")\n        batch_op.drop_column("partner_channel_id")\n        batch_op.drop_column("partner_ad_text")\n', 'bot/views/partner_posts.py': '"""Owner-authored, per-server partner posts for #find-partners."""\n\nfrom __future__ import annotations\n\nimport logging\nfrom typing import TYPE_CHECKING\n\nimport discord\n\nfrom bot.database import repository\nfrom bot.database.models import Listing, ListingStatus\nfrom bot.services import permissions\nfrom bot.services.errors import LISTING_GONE, NotFound, ValidationError\nfrom bot.utils.helpers import listing_jump_url, truncate, utcnow\nfrom bot.utils.mentions import safe_allowed_mentions\nfrom bot.views import self_post\nfrom bot.views.base import ConfirmView, OwnedView, get_bot, handle_error, home_button, reply\nfrom bot.views.welcome import action_button, persistent_view, register_action, show_screen\n\nif TYPE_CHECKING:\n    from bot.core import WaypointBot\n\nlog = logging.getLogger(__name__)\n\n\ndef partner_post_url(bot: WaypointBot, listing: Listing) -> str | None:\n    return listing_jump_url(\n        bot.runtime.hub.main_guild_id,\n        listing.partner_channel_id,\n        listing.partner_message_id,\n    )\n\n\ndef partner_post_controls(bot: WaypointBot, guild_id: int) -> discord.ui.View:\n    """Actions under a partner post are intentionally different from server-directory actions."""\n    from bot.views.partnership import RequestPartnershipButton, view_ad_button\n\n    return persistent_view(\n        view_ad_button(bot, guild_id, label="View Server Ad"),\n        RequestPartnershipButton(\n            guild_id,\n            label="Send Partner Request",\n            emoji="🤝",\n            style=discord.ButtonStyle.success,\n        ),\n    )\n\n\nasync def _active_managed_listings(bot: WaypointBot, user_id: int) -> tuple[list[Listing], dict[int, discord.Guild]]:\n    guilds = {g.id: g for g in permissions.cached_manageable_guilds(bot, user_id)}\n    async with bot.db.session() as session:\n        rows = await repository.get_listings(session, guilds.keys())\n    rows = [row for row in rows if row.status == ListingStatus.ACTIVE and row.guild_id in guilds]\n    rows.sort(key=lambda row: guilds[row.guild_id].name.lower())\n    return rows, guilds\n\n\n@register_action("partner_posts")\nasync def partner_posts_action(interaction: discord.Interaction) -> None:\n    await start_partner_posts(interaction)\n\n\nasync def start_partner_posts(interaction: discord.Interaction) -> None:\n    """Open the one-per-server partner-post manager, using a dropdown only when needed."""\n    bot = get_bot(interaction)\n    rows, guilds = await _active_managed_listings(bot, interaction.user.id)\n\n    if not rows:\n        await reply(\n            interaction,\n            "List a server first, then you can post what that server is looking for.",\n            view=persistent_view(action_button(bot, "post"), home_button(bot)),\n        )\n        return\n\n    if len(rows) == 1:\n        await show_partner_management(interaction, rows[0].guild_id)\n        return\n\n    from bot.views.partnership import GuildPickerView\n\n    async def picked(inter: discord.Interaction, guild_id: int) -> None:\n        await show_partner_management(inter, guild_id)\n\n    embed = discord.Embed(\n        title="My Partner Posts",\n        description="Choose which server you want to manage.",\n        color=bot.runtime.bot.color_primary,\n    )\n    await reply(\n        interaction,\n        embed=embed,\n        view=GuildPickerView(\n            interaction.user.id,\n            [(row.guild_id, guilds[row.guild_id].name) for row in rows],\n            picked,\n            placeholder="Choose a server",\n        ),\n    )\n\n\nclass PartnerPostManager(OwnedView):\n    def __init__(\n        self,\n        bot: WaypointBot,\n        owner_id: int,\n        guild: discord.Guild,\n        listing: Listing,\n    ) -> None:\n        super().__init__(owner_id)\n        self.bot = bot\n        self.guild = guild\n        self.listing = listing\n        self._build()\n\n    def _build(self) -> None:\n        live = bool(self.listing.partner_message_id and self.listing.partner_channel_id)\n        if live:\n            edit = discord.ui.Button(label="Edit Partner Ad", style=discord.ButtonStyle.primary, row=0)\n            edit.callback = self._edit  # type: ignore[method-assign]\n            self.add_item(edit)\n\n            url = partner_post_url(self.bot, self.listing)\n            if url:\n                self.add_item(discord.ui.Button(label="View Live Post", url=url, row=0))\n\n            delete = discord.ui.Button(label="Delete Partner Post", style=discord.ButtonStyle.danger, row=1)\n            delete.callback = self._delete  # type: ignore[method-assign]\n            self.add_item(delete)\n        else:\n            post = discord.ui.Button(label="Post Partner Ad", style=discord.ButtonStyle.success, row=0)\n            post.callback = self._post  # type: ignore[method-assign]\n            self.add_item(post)\n\n        self.add_item(home_button(self.bot, row=2))\n\n    async def _post(self, interaction: discord.Interaction) -> None:\n        try:\n            await open_partner_post_window(interaction, self.guild.id)\n        except Exception as exc:  # noqa: BLE001\n            await handle_error(interaction, exc)\n\n    async def _edit(self, interaction: discord.Interaction) -> None:\n        try:\n            await open_partner_post_window(interaction, self.guild.id)\n        except Exception as exc:  # noqa: BLE001\n            await handle_error(interaction, exc)\n\n    async def _delete(self, interaction: discord.Interaction) -> None:\n        try:\n            await delete_partner_post(interaction, self.guild.id)\n        except Exception as exc:  # noqa: BLE001\n            await handle_error(interaction, exc)\n\n\ndef partner_management_embed(bot: WaypointBot, guild: discord.Guild, listing: Listing) -> discord.Embed:\n    live = bool(listing.partner_message_id and listing.partner_channel_id)\n    embed = discord.Embed(\n        title="🤝 Partner Post",\n        description=f"**{guild.name}**\\n{\'🟢 Live in #find-partners\' if live else \'⚪ No partner post yet\'}",\n        color=bot.runtime.bot.color_primary,\n    )\n    if listing.partner_ad_text:\n        embed.add_field(\n            name="Current post",\n            value=truncate(listing.partner_ad_text, 850),\n            inline=False,\n        )\n    if guild.icon:\n        embed.set_thumbnail(url=guild.icon.url)\n    embed.set_footer(text="Each server has its own partner post. Posting one opens partnership requests for that server.")\n    return embed\n\n\nasync def _load(bot: WaypointBot, guild_id: int, user_id: int) -> tuple[discord.Guild, Listing]:\n    guild, _member = await permissions.require_manager(bot, guild_id, user_id)\n    async with bot.db.session() as session:\n        listing = await repository.get_listing(session, guild_id)\n    if listing is None or listing.status != ListingStatus.ACTIVE:\n        raise NotFound(LISTING_GONE)\n    return guild, listing\n\n\nasync def show_partner_management(interaction: discord.Interaction, guild_id: int) -> None:\n    bot = get_bot(interaction)\n    guild, listing = await _load(bot, guild_id, interaction.user.id)\n    await show_screen(\n        interaction,\n        embed=partner_management_embed(bot, guild, listing),\n        view=PartnerPostManager(bot, interaction.user.id, guild, listing),\n    )\n\n\nasync def _adopt_partner_post(\n    bot: WaypointBot,\n    guild_id: int,\n    text: str,\n    message: discord.Message,\n    actor_id: int,\n) -> None:\n    channel = bot.panels.looking_channel()\n    if channel is None or message.channel.id != channel.id:\n        raise ValidationError("The find-partners channel changed while you were posting. Try again.")\n\n    async with bot.db.session() as session:\n        listing = await repository.get_listing(session, guild_id)\n        if listing is None or listing.status != ListingStatus.ACTIVE:\n            raise NotFound(LISTING_GONE)\n        old_channel = listing.partner_channel_id\n        old_message = listing.partner_message_id\n        old_controls = listing.partner_controls_message_id\n\n    controls = await channel.send(\n        content="-# Partner actions",\n        view=partner_post_controls(bot, guild_id),\n        allowed_mentions=safe_allowed_mentions(),\n    )\n\n    now = utcnow()\n    async with bot.db.session() as session:\n        current = await repository.get_listing(session, guild_id)\n        if current is None:\n            raise NotFound(LISTING_GONE)\n        current.partner_ad_text = text\n        current.partner_channel_id = channel.id\n        current.partner_message_id = message.id\n        current.partner_controls_message_id = controls.id\n        current.partner_posted_at = now\n        current.accepting_partnerships = True\n        current.updated_at = now\n        await repository.add_audit(\n            session,\n            "partner_post.saved",\n            actor_id=actor_id,\n            guild_id=guild_id,\n            details={"message_id": message.id},\n        )\n\n    if old_message and old_message != message.id:\n        await bot.panels.delete_listing_message(old_channel, old_message)\n    if old_controls and old_controls != controls.id:\n        await bot.panels.delete_listing_message(old_channel, old_controls)\n\n    await bot.panels.move_looking_panel_now()\n    log.info("partner_post.saved guild_id=%s message_id=%s", guild_id, message.id)\n\n\nasync def open_partner_post_window(interaction: discord.Interaction, guild_id: int) -> None:\n    bot = get_bot(interaction)\n    guild, _listing = await _load(bot, guild_id, interaction.user.id)\n    channel = bot.panels.looking_channel()\n    if channel is None:\n        raise ValidationError("The find-partners channel isn\'t set up yet.")\n\n    await interaction.response.defer(ephemeral=True, thinking=True)\n\n    async def accepted(text: str, message: discord.Message) -> None:\n        await _adopt_partner_post(bot, guild_id, text, message, interaction.user.id)\n\n    note = await self_post.run_submission(\n        interaction,\n        guild_id,\n        guild.name,\n        channel=channel,\n        post_title="Partner ad",\n        retry_hint="My Partner Posts",\n        allow_review=False,\n        respect_approval_required=False,\n        on_accept=accepted,\n        success_text="## Partner ad posted\\nYour server is now visible in **Find a Partner**.",\n    )\n    await interaction.edit_original_response(\n        content=note,\n        view=persistent_view(action_button(bot, "partner_posts"), home_button(bot)),\n    )\n\n\nasync def _clear_partner_fields(\n    bot: WaypointBot,\n    guild_id: int,\n    *,\n    actor_id: int | None = None,\n) -> tuple[int | None, int | None, int | None]:\n    async with bot.db.session() as session:\n        listing = await repository.get_listing(session, guild_id)\n        if listing is None:\n            return None, None, None\n        old = (listing.partner_channel_id, listing.partner_message_id, listing.partner_controls_message_id)\n        listing.partner_ad_text = None\n        listing.partner_channel_id = None\n        listing.partner_message_id = None\n        listing.partner_controls_message_id = None\n        listing.partner_posted_at = None\n        listing.updated_at = utcnow()\n        if actor_id is not None:\n            await repository.add_audit(session, "partner_post.deleted", actor_id=actor_id, guild_id=guild_id)\n        return old\n\n\nasync def delete_partner_post(interaction: discord.Interaction, guild_id: int) -> None:\n    bot = get_bot(interaction)\n    guild, listing = await _load(bot, guild_id, interaction.user.id)\n    if not listing.partner_message_id:\n        await show_partner_management(interaction, guild_id)\n        return\n\n    confirm = ConfirmView(interaction.user.id, confirm_label="Delete Partner Post")\n    await reply(interaction, f"Delete the partner post for **{guild.name}**?", view=confirm)\n    await confirm.wait()\n    if not confirm.confirmed or confirm.interaction is None:\n        return\n\n    done = confirm.interaction\n    await done.response.defer()\n    await permissions.require_manager(bot, guild_id, done.user.id)\n    channel_id, message_id, controls_id = await _clear_partner_fields(bot, guild_id, actor_id=done.user.id)\n    await bot.panels.delete_listing_message(channel_id, message_id)\n    await bot.panels.delete_listing_message(channel_id, controls_id)\n    await bot.panels.move_looking_panel_now()\n    await done.edit_original_response(content=f"Partner post deleted for **{guild.name}**.", view=None)\n\n\nasync def handle_direct_edit(bot: WaypointBot, before: discord.Message, after: discord.Message) -> None:\n    """Direct Discord edits are removed so moderation cannot be bypassed."""\n    async with bot.db.session() as session:\n        listing = await repository.get_listing_by_partner_message(session, after.id)\n    if listing is None:\n        return\n\n    controls_id = listing.partner_controls_message_id\n    channel_id = listing.partner_channel_id\n    guild_id = listing.guild_id\n    try:\n        await after.delete()\n    except discord.HTTPException as exc:\n        log.warning("Could not remove directly edited partner post %s: %s", after.id, exc)\n        return\n\n    await _clear_partner_fields(bot, guild_id)\n    await bot.panels.delete_listing_message(channel_id, controls_id)\n    await bot.panels.move_looking_panel_now()\n\n    try:\n        await after.author.send(\n            "Your partner post was edited directly, so Parley removed it so changes cannot bypass moderation.\\n\\n"\n            "Use **My Partner Posts → Edit Partner Ad** to post the replacement.",\n            view=persistent_view(action_button(bot, "partner_posts")),\n        )\n    except discord.HTTPException:\n        pass\n\n\nasync def handle_raw_delete(bot: WaypointBot, channel_id: int, message_id: int) -> None:\n    """Clear stored state if an owner manually deletes their live partner post."""\n    async with bot.db.session() as session:\n        listing = await repository.get_listing_by_partner_message(session, message_id)\n    if listing is None:\n        return\n\n    controls_id = listing.partner_controls_message_id\n    guild_id = listing.guild_id\n    await _clear_partner_fields(bot, guild_id)\n    await bot.panels.delete_listing_message(channel_id, controls_id)\n    await bot.panels.move_looking_panel_now()\n', 'tests/unit/test_partner_posts.py': 'from __future__ import annotations\n\nimport discord\n\nfrom bot.database.models import Listing\nfrom bot.views.partner_posts import PartnerPostManager, partner_post_controls\nfrom tests.fakes import USER_ID, FakeBot\n\n\ndef _labels(view):\n    return [getattr(getattr(c, "item", c), "label", None) for c in view.children]\n\n\ndef test_partner_post_public_actions_are_distinct_from_server_directory(db):\n    bot = FakeBot(db)\n    view = partner_post_controls(bot, 123)\n    assert _labels(view) == ["View Server Ad", "Send Partner Request"]\n    buttons = [getattr(c, "item", c) for c in view.children]\n    assert buttons[1].style is discord.ButtonStyle.success\n\n\ndef test_partner_post_manager_switches_between_post_and_edit_delete(db):\n    bot = FakeBot(db)\n    guild = bot.guild\n\n    empty = Listing(guild_id=guild.id, advertisement_text="server ad", category="Gaming")\n    assert _labels(PartnerPostManager(bot, USER_ID, guild, empty)) == ["Post Partner Ad", "Home"]\n\n    live = Listing(\n        guild_id=guild.id,\n        advertisement_text="server ad",\n        category="Gaming",\n        partner_ad_text="Looking for anime communities",\n        partner_channel_id=10,\n        partner_message_id=11,\n    )\n    assert _labels(PartnerPostManager(bot, USER_ID, guild, live)) == [\n        "Edit Partner Ad", "View Live Post", "Delete Partner Post", "Home"\n    ]\n'}

# Validate and build every changed file in memory first.
for path, old, new, label in REPLACEMENTS:
    apply_replace(path, old, new, label)

for path, start, end, replacement, label in SECTIONS:
    apply_section(path, start, end, replacement, label)

for path, content in NEW_FILES.items():
    p = ROOT / path
    if p.exists():
        raise SystemExit(
            f"[STOP] Refusing to overwrite existing new file: {path}\nNo project files were written."
        )
    state[path] = content
    new_paths.add(path)

# Full visible-name rebrand. Preserve lowercase technical compatibility names
# such as wp: custom IDs, waypoint.db, the CI database user, and migration IDs.
TEXT_SUFFIXES = {".py", ".md", ".txt", ".bat", ".yml", ".yaml", ".toml", ".ini", ".json"}
SPECIAL_NAMES = {"Dockerfile", ".env.example", ".gitignore"}

for p in ROOT.rglob("*"):
    if not p.is_file() or p.resolve() == SELF:
        continue
    if any(part in {".git", ".venv", "__pycache__", ".pytest_cache"} for part in p.parts):
        continue
    if p.name == ".env":
        continue
    if p.suffix.lower() not in TEXT_SUFFIXES and p.name not in SPECIAL_NAMES:
        continue
    rel = str(p.relative_to(ROOT))
    text = state.get(rel)
    if text is None:
        try:
            text = p.read_text(encoding="utf-8")
        except (UnicodeDecodeError, OSError):
            continue
        original.setdefault(rel, text)
    new = text.replace("WAYPOINT", "PARLEY").replace("Waypoint", "Parley")
    new = new.replace("waypoint.log", "parley.log")
    if new != text:
        state[rel] = new

old_fixer = ROOT / "fix_parley_ci.py"
if old_fixer.exists():
    removed_paths.add("fix_parley_ci.py")

# Only now, after all validation succeeded, write the project.
changed: list[str] = []
for path, text in state.items():
    p = ROOT / path
    old = original.get(path)
    if old == text:
        continue
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(text, encoding="utf-8", newline="\n")
    changed.append(path)

for path in removed_paths:
    p = ROOT / path
    if p.exists():
        p.unlink()
        changed.append(path + " (removed)")

print()
print("[OK] Parley partner-flow update applied.")
print()
print("Changed:")
for item in sorted(set(changed)):
    print(f"  - {item}")
print()
print("New behavior:")
print("  - Server Directory and Find a Partner are both controlled read-only feeds")
print("  - managers post their own partner ad in a short one-message window")
print("  - one independent partner post per server, with a dropdown for multiple servers")
print("  - partner posts can be edited, viewed, and deleted")
print("  - Browse Partners goes straight to matches instead of a category wall")
print("  - finder buttons are different from Server Directory buttons")
print("  - Start Here routes people to Server Directory or Find a Partner")
print("  - visible Waypoint branding is now Parley")
print()
print("Run next:")
print("  python -m pytest -q")
print("  python -m pyflakes bot tests migrations")
print("  git diff --check")
